def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

count = 0
for n in range(2, 200):
    if gcd(n, 6) == 1:
        count += 1

print(count)

def count_coprime(limit):
    count = 0
    for n in range(2, limit):
        if n % 2 != 0 and n % 3 != 0:
            count += 1
    return count

count = count_coprime(200)
print(f"Number of positive integers n < 200 such that gcd(n, 6) = 1: {count}")
